const resources = Object.fromEntries(localeCodes.map(code => [
  code,
  { ...(regionalPartial[code] || {}), ...({ en, hi, kn }[code] || {}), ...supplementalTranslations[code], ...resultTranslations[code], ...resultDetailTranslations[code], ...(regionalCompleteTranslations[code] || {}) }
]))
const englishKeys = Object.keys(resources.en)
const missingTranslations = Object.fromEntries(
  localeCodes.map(code => [code, englishKeys.filter(key => !(key in resources[code]))])
)
const languageNames = Object.fromEntries(localeCodes.map(code => [
  code,
  missingTranslations[code].length ? `${regionalNames[code]} (partial)` : regionalNames[code]
]))

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: Object.fromEntries(Object.entries(resources).map(([code, value]) => [code, { translation: value }])),
    supportedLngs: localeCodes,
    fallbackLng: 'en',
    interpolation: { escapeValue: false },
    detection: {
      order: ['localStorage'],
      lookupLocalStorage: 'agritech-language',
      caches: ['localStorage']
    }
  })

export function t(lang = 'en') {
  const safeLang = resources[lang] ? lang : 'en'
  return new Proxy(resources[safeLang], {
    get(target, key) {
      return Object.prototype.hasOwnProperty.call(target, key) ? target[key] : en[key]
    }
  })
}

export function setAppLanguage(lang) {
  const safeLang = resources[lang] ? lang : 'en'
  i18n.changeLanguage(safeLang)
  if (typeof localStorage !== 'undefined') localStorage.setItem('agritech-language', safeLang)
  if (typeof document !== 'undefined') document.documentElement.lang = safeLang
  return safeLang
}

export function getTranslationCoverage(lang) {
  const safeLang = resources[lang] ? lang : 'en'
  return {
    translated: englishKeys.length - missingTranslations[safeLang].length,
    total: englishKeys.length,
    missing: missingTranslations[safeLang]
  }
}

export { i18n, languageNames, missingTranslations }
